package env

import (
	"bytes"
	"strings"
	"text/template"

	"github.com/zhide915/tamp/internal/frappe"
)

// ComposeFile is the generated compose file in an environment's directory.
const ComposeFile = "compose.yaml"

// CacheVolume holds the pip and yarn caches that every environment shares.
const CacheVolume = "tamp-cache"

// benchVolume is created by tamp, not compose: it carries the Frappe branch
// as a label, and a volume's labels are fixed when it is created.
func benchVolume(name string) string { return name + "_bench" }

// Container labels: the only record of which environments exist.
const (
	LabelEnv  = "tamp.env"
	LabelPath = "tamp.path"
	// LabelFrappe on the bench volume is the branch the bench was built for.
	LabelFrappe = "tamp.frappe"
)

// frappeContainer is compose's name for the environment's frappe container.
func frappeContainer(name string) string { return name + "-frappe-1" }

// network is compose's default network for the environment, which the
// router joins.
func network(name string) string { return name + "_default" }

// The services' hostnames on the environment's network.
const (
	dbService         = "mariadb"
	redisCacheService = "redis-cache"
	redisQueueService = "redis-queue"
)

type composeData struct {
	QuotedName                      string
	BenchImage, MariaDBImage, Redis string
	BenchVolume, CacheVolume        string
	BenchDir, AppsDir, CacheDir     string
	Procfile, DBRootPassword        string
	Labels, RedisServices           []string
}

// renderCompose renders compose.yaml for an environment from its recipe.
func renderCompose(name, dir, image string, r Recipe) ([]byte, error) {
	var buf bytes.Buffer
	err := composeTemplate.Execute(&buf, composeData{
		QuotedName:     quote(name),
		BenchImage:     image,
		MariaDBImage:   "mariadb:" + matrix[r.Frappe].MariaDB,
		Redis:          RedisImage,
		BenchVolume:    benchVolume(name),
		CacheVolume:    CacheVolume,
		BenchDir:       frappe.BenchDir,
		AppsDir:        frappe.AppsDir,
		CacheDir:       frappe.CacheDir,
		Procfile:       frappe.Procfile,
		DBRootPassword: frappe.DBRootPassword,
		RedisServices:  []string{redisCacheService, redisQueueService},
		Labels:         []string{LabelEnv + ": " + quote(name), LabelPath + ": " + quote(dir)},
	})
	return buf.Bytes(), err
}

// quote is a YAML single-quoted string, in which a backslash, as in a
// Windows path, is literal.
func quote(s string) string { return "'" + strings.ReplaceAll(s, "'", "''") + "'" }

var composeTemplate = template.Must(template.New(ComposeFile).Parse(`# Generated by tamp from tamp.toml on every build. Edit tamp.toml instead.
name: {{.QuotedName}}

services:
  frappe:
    image: {{.BenchImage}}
    # Idles until tamp writes the Procfile, then runs the bench's processes.
    command: [bash, -c, 'until [ -f {{.Procfile}} ]; do sleep 1; done; exec honcho start']
    environment:
      # develop's web server binds loopback without it, out of the router's reach.
      FRAPPE_BIND_ADDR: 0.0.0.0
    labels:
{{- range .Labels}}
      {{.}}
{{- end}}
    volumes:
      - bench:{{.BenchDir}}
      - ./apps:{{.AppsDir}}
      - tamp-cache:{{.CacheDir}}
    depends_on:
      mariadb:
        condition: service_healthy
      redis-cache:
        condition: service_healthy
      redis-queue:
        condition: service_healthy

  mariadb:
    image: {{.MariaDBImage}}
    # Site creation fails on collation errors without these.
    command:
      - --character-set-server=utf8mb4
      - --collation-server=utf8mb4_unicode_ci
      - --skip-character-set-client-handshake
    environment:
      MARIADB_ROOT_PASSWORD: {{.DBRootPassword}}
    labels:
{{- range .Labels}}
      {{.}}
{{- end}}
    volumes:
      - db:/var/lib/mysql
    healthcheck:
      # --connect fails while the entrypoint's socket-only setup server runs.
      test: [CMD, healthcheck.sh, --connect, --innodb_initialized]
      interval: 5s
      timeout: 5s
      retries: 20
      start_period: 30s
{{range $service := .RedisServices}}
  {{$service}}:
    image: {{$.Redis}}
    # Redis keeps no data. The tmpfs covers the image's /data, which would
    # otherwise become an anonymous volume.
    command: [redis-server, --save, '', --appendonly, 'no']
    tmpfs: [/data]
    labels:
{{- range $.Labels}}
      {{.}}
{{- end}}
    healthcheck:
      test: [CMD, redis-cli, ping]
      interval: 5s
      timeout: 3s
      retries: 10
{{end}}
volumes:
  db: {}
  bench:
    name: {{.BenchVolume}}
    external: true
  tamp-cache:
    name: {{.CacheVolume}}
    external: true
`))
